<script>
(function(){
  const modal=document.getElementById('apply-modal'),title=document.getElementById('apply-job-title'),meta=document.getElementById('apply-job-meta'),posInput=document.getElementById('apply-position-input');
  function openModal(job,loc,type){if(title)title.textContent=job;if(meta)meta.textContent=(type?type+' · ':'')+(loc||'Remote')+' position';if(posInput)posInput.value=job||'';if(modal)modal.classList.add('open');document.body.style.overflow='hidden'}
  function closeModal(){if(modal)modal.classList.remove('open');document.body.style.overflow=''}
  document.querySelectorAll('.apply-btn').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();openModal(btn.dataset.job,btn.dataset.location,btn.dataset.type)}));
  document.querySelectorAll('[data-apply-close]').forEach(b=>b.addEventListener('click',closeModal));
  if(modal){modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeModal()})}
})();
</script>
